private MutationTestSummaryData createSummaryData(
    final CoverageDatabase coverage, final ClassMutationResults data) {
  final Collection<ClassInfo> classInfos = getClassInfoFromCoverage(coverage, data.getMutatedClass());
  return new MutationTestSummaryData(data.getFileName(),
      data.getMutations(), classInfos);
}

/**
 * Gets ClassInfo from CoverageDatabase.
 * In pitest 1.10.0+, CoverageDatabase no longer has getClassInfo method.
 * We access the internal CodeSource from CoverageData via reflection.
 */
@SuppressWarnings("unchecked")
private Collection<ClassInfo> getClassInfoFromCoverage(
    CoverageDatabase coverage, org.pitest.classinfo.ClassName className) {
  try {
    // CoverageData has a private 'code' field of type CodeSource
    Field codeField = CoverageData.class.getDeclaredField("code");
    codeField.setAccessible(true);
    CodeSource codeSource = (CodeSource) codeField.get(coverage);
    // Use fetchClass to get ClassInfo
    return codeSource.getClassInfo(Collections.singleton(className));
  } catch (ReflectiveOperationException e) {
    // Fallback: return empty collection if reflection fails
    throw new RuntimeException("Failed to access CodeSource from CoverageData", e);
  }
}

